import math

def solve_block_number_length(n):
    """Calculate total digits in block 1 to n"""
    count = 0
    for i in range(1, n + 1):
        if i == 0:
            continue
        count += len(str(i))
    return count

def get_digits_of_range(numbers, k):
    """Find digit at position k within concatenated string of numbers from 1 to numbers"""
    for num in range(1, numbers + 1):
        s = str(num)
        if k <= len(s):
            return int(s[k - 1])
        k -= len(s)
    return -1

def get_length_of_numbers_with_d(num_digits):
    """Count how many numbers have exactly num_digits"""
    if num_digits == 1:
        return 9  # 1-9
    return 9 * (10 ** (num_digits - 1))

def get_start_of_block(num_digits):
    """Get the starting number for numbers with num_digits """
    return 10 ** (num_digits - 1)

def get_length_for_numbers(count, num_digits):
    """Total digits contributed by count numbers with num_digits """
    return count * num_digits

def find_digit_at_position(k):
    """Find the digit at position k in the sequence"""
    # Find which block contains position k
    block_length = 0
    block_num = 1

    while True:
        # Calculate length of block_num
        block_len = 0
        for i in range(1, block_num + 1):
            block_len += len(str(i))

        if block_num > 0 and block_len + block_length > k:
            break

        block_length += block_len
        block_num += 1

    # Now we know the digit is in block (block_num - 1)
    num_block = block_num - 1

    # Find which number in the block contains our position
    current_pos = k - block_length

    if current_pos == 0:
        return 1  # First digit of first number in block

    # Find which number in 1, 2, ..., num_block contains the position
    for num in range(1, num_block + 1):
        num_str = str(num)
        if current_pos <= len(num_str):
            return int(num_str[current_pos - 1])
        current_pos -= len(num_str)

    return -1

def solution(input_str):
    """Process all queries from input string"""
    lines = input_str.strip().split('\n')
    q = int(lines[0])

    results = []
    for i in range(1, q + 1):
        k = int(lines[i])
        digit = find_digit_at_position(k)
        results.append(str(digit))

    return '\n'.join(results)

if __name__ == "__main__":
