def solve():
    """
    Solves the problem of finding minimal moves to arrange divisors of n
    in a circle such that adjacent numbers are not coprime.
    """
    def get_divisors(n):
        """Get all divisors of n greater than 1"""
        divs = []
        for i in range(2, int(math.isqrt(n)) + 1):
            if n % i == 0:
                divs.append(i)
                if i * i != n:
                    divs.append(n // i)
        divs.append(n)
        divs.sort()
        return divs

    def gcd(a, b):
        return math.gcd(a, b)

    def lcm(a, b):
        return abs(a * b) // gcd(a, b)

    def find_prime_factors(n):
        """Find prime factorization of n"""
        factors = defaultdict(int)
        d = 2
        while d * d <= n:
            while n % d == 0:
                factors[d] += 1
                n //= d
            d += 1
        if n > 1:
            factors[n] += 1
        return list(factors.items())

    try:
        data = sys.stdin.read().split()
    except Exception:
        return ""

    idx = 0
    t = int(data[idx])
    idx += 1

    results = []

    for _ in range(t):
        n = int(data[idx])
        idx += 1

        # Get all divisors > 1
        divisors = [d for d in range(2, n + 1) if n % d == 0]
        divisors.sort()
        m = len(divisors)

        # Find prime factorization of n
        pf = find_prime_factors(n)
        unique_primes = set(p[0] for p in pf)

        # If all divisors share a common prime, 0 moves
        if len(unique_primes) == 1:
            # All share same prime, 0 moves
            rev_divs = list(divisors)
            results.append(" ".join(map(str, rev_divs)) + "\n0\n")
            continue

        # Strategy: Try to arrange divisors by grouping by their prime factors
        # Build adjacency based on shared primes
        adj = [set() for _ in range(m)]
        for i in range(m):
            for j in range(i + 1, m):
                if gcd(divisors[i], divisors[j]) > 1:
                    adj[i].add(j)
                    adj[j].add(i)

        # Greedy approach: Start from first divisor, pick next if not coprime
        start = 0
        visited = [False] * m
        visited[start] = True
        order = [divisors[start]]

        # Build path
        for i in range(m):
            found = False
            for j in range(m):
                if not visited[j] and gcd(divisors[start if i == 0 else order[-1]], divisors[j]) > 1:
                    order.append(divisors[j])
                    visited[j] = True
                    found = True
                    break
            if not found:
                order.append(divisors[i])
                visited[i] = True

        # Check if all adjacent pairs are not coprime
        cnt = 0
        for i in range(len(order)):
            if i == 0:
                continue
            if gcd(order[i], order[i-1]) == 1:
                cnt += 1

        results.append(" ".join(map(str, order)) + f"\n{cnt}\n")

    return "".join(results)

def solution(input_str):
    return solve()
