def find_long_path(adj, n, k):
    """Find a simple path of length >= n/k"""
    target_len = n // k

    # Simple BFS to find longest path
    visited = set()
    max_path = []

    for start in range(1, n + 1):
        if start in visited:
            continue
        stack = [(start, [start])]
        path_found = None

        while stack:
            u, path = stack.pop()
            if len(path) == target_len + 1:
                path_found = path
                break

            for v in adj[u]:
                if v not in visited or path[-1] == v:
                    if v not in set(path):
                        stack.append((v, path + [v]))

        if path_found:
            max_path = path_found
            break

    return max_path if len(max_path) >= target_len else []

