                min_cost = cost
                c = 1
                rem_idx = [edge['idx']]

    if min_cost != float('inf'):
        return f"{min_cost}\n{c}\n{' '.join(map(str, rem_idx))}\n"

    # Try removing 2 edges
    for i in range(min(m, 600)):
        for j in range(i + 1, min(m, 600)):
            adj = build_adj({edges[i]['idx'], edges[j]['idx']})
            cost = edges[i]['w'] + edges[j]['w']
            if cost >= min_cost:
