    cost_matrix = [[0] * N for _ in range(N)]

    for i in range(N):
        row = list(map(int, lines[i + 1].split()))
        # row has N-1 values (all cities except self)
        for j in range(N):
            if i == j:
                cost_matrix[i][j] = float('inf')  # diagonal
            else:
                # Determine position in row
                if j < i:
                    pos = j
                else:
                    pos = j + 1
                if pos < len(row):
                    cost_matrix[i][j] = row[pos]
                else:
                    cost_matrix[i][j] = float('inf')

    # Build preference lists (lower cost = better preference)
    prefs = []
    for i in range(N):
        others = []
        for j in range(N):
            if i == j:
                continue
            others.append((cost_matrix[i][j], j))
        others.sort()
        prefs.append([j for _, j in others])

    # Gale-Shapley: cities propose to each other
    engaged = [-1] * N  # engaged_to[i] = j means i is engaged to j
    p_index = [0] * N  # current proposal index for each city

    while True:
        matched = True
        for i in range(N):
            if engaged[i] == -1:
                matched = False
                break

        if matched:
            break

        # Find an unmatched city that can still propose
        i = -1
        for j in range(N):
            if engaged[j] == -1:
                i = j
                break

        if i == -1:
            break

        # City i proposes to its preferred cities
        prop_index = 0
        while True:
            if prop_index >= len(prefs[i]):
                # No one to propose to
                engaged[i] = -2  # Special marker for no match possible
                break

            j = prefs[i][prop_index]
            if cost_matrix[i][j] == float('inf') or cost_matrix[j][i] == float('inf'):
                prop_index += 1
                continue

            # City j receives proposal from i
            current_engaged = engaged[i]
            if current_engaged == -1:
                engaged[i] = j
                engaged[j] = i
                break
            else:
                person = current_engaged
                old_cost = cost_matrix[person][j]
                new_cost = cost_matrix[person][i]

                if new_cost < old_cost:
                    engaged[i] = j
                    engaged[j] = i
                    engaged[person] = -1
                prop_index += 1

    # Check for valid matching
    for i in range(N):
        if engaged[i] == -2:
            return "-1\n"
        if engaged[i] == -1:
            return "-1\n"
        if engaged[i] == i:
            return "-1\n"

    # Build result string
    result = []
    for i in range(N):
        j = engaged[i]
        if j == -1:
            result.append("-1")
        else:
            result.append(str(j + 1))  # Convert to 1-indexed
        result.append("\n" if i < N - 1 else "")

    return "\n".join(result)
