def solution(input_str):
    lines = input_str.strip().split('\n')
    N = int(lines[0])

    # Build the full cost matrix (N x N)
    cost_matrix = [[0] * N for _ in range(N)]

    for i in range(N):
        row = list(map(int, lines[i + 1].split()))
        pos = 0
        for j in range(N):
            if i != j:
                cost_matrix[i][j] = row[pos]
                pos += 1
            else:
                cost_matrix[i][j] = float('inf')

    # Build preference lists for each city
    # Each preference list will be sorted by cost (lower is better)
    prefs = []
    for i in range(N):
        others = []
        for j in range(N):
            if i == j:
                continue
            others.append((cost_matrix[i][j], j))
        others.sort()
        prefs.append([j for _, j in others])

    # Gale-Shapley algorithm with cities as proposers
    engaged = [-1] * N  # engaged[i] stores who city i is paired with
    proposal_ptr = [0] * N  # pointer to current preference city for each proposer

    while True:
        matched = True
        for i in range(N):
            if engaged[i] == -1:
                matched = False
                break

        if matched:
            break

        # Find an unmatched city
        i = -1
        for cand in range(N):
            if engaged[cand] == -1 and proposal_ptr[cand] < len(prefs[cand]):
                i = cand
                break

        if i == -1:
            return "-1\n"

        # City i proposes to its next preferred city
        j = prefs[i][proposal_ptr[i]]
        proposal_ptr[i] += 1

        # Case 1: j is unmatched
        if engaged[j] == -1:
            engaged[i] = j
            engaged[j] = i
        else:
            # Case 2: j is already matched with k
            k = engaged[j]
            # j compares i and k based on cost
            if cost_matrix[j][i] < cost_matrix[j][k]:
                # j prefers i
                engaged[i] = j
                engaged[j] = i
                engaged[k] = -1
            # else j keeps k, i remains unmatched

    # Verify all cities are matched
    for i in range(N):
        if engaged[i] == -1:
            return "-1\n"
        if engaged[i] == i:
            return "-1\n"

    # Build output (1-indexed)
    result = []
    for i in range(N):
        j = engaged[i]
        result.append(str(j + 1))

    return "\n".join(result)
