        return s1

    # Precompute KMP failure function for virus
    failure_state = [0] * vlen
    j = 0
    for idx in range(1, vlen):
        while j > 0 and virus[idx] != virus[j]:
            j = failure_state[j-1]
        if virus[idx] == virus[j]:
            j += 1
        failure_state[idx] = j

    # DP: dp[i][j][k] = length of LCS of s1[:i] and s2[:j] ending with virus prefix match k
    # Using dictionary to save space
    dp = {}
    parent = {}

    dp[(0, 0, 0)] = 0
    parent[(0, 0, 0)] = None

    for i in range(n + 1):
        for j in range(m + 1):
            for k in range(vlen):
                if (i, j, k) not in dp:
                    continue

                # Option 1: Skip s1[i]
                if i < n and (i+1, j, 0) not in dp:
                    # Compute next k after adding s1[i] isn't needed here since we skip
                    # We just carry over the same k
                    pass

                # Option 2: Skip s2[j]
                if j < m and (i, j+1, 0) not in dp:
                    pass

                # Option 3: If matching chars
                if i > 0 and j > 0 and s1[i-1] == s2[j-1]:
                    char = s1[i-1]
                    new_k = compute_next_state(virus, k, char)
                    if new_k != vlen:
                        new_len = dp.get((i-1, j-1, k), -1)
                        if new_len + 1 > dp.get((i, j, k), -1):
                            dp[(i, j, k)] = new_len + 1
                            parent[(i, j, k)] = ((i-1, j-1, k), char)

                # Option 4: Skip via previous states
                prev_len_top = dp.get((i-1, j, k), 0)
                prev_len_left = dp.get((i, j-1, k), 0)
                prev_len_diag = dp.get((i-1, j-1, k), 0)

                best = max(prev_len_top, prev_len_left, prev_len_diag + 1 if s1[i-1] == s2[j-1] and compute_next_state(virus, k, s1[i-1]) != vlen else prev_len_diag)

                if best > dp.get((i, j, k), -1):
                    dp[(i, j, k)] = best
                    if best == prev_len_diag + 1 and s1[i-1] == s2[j-1] and compute_next_state(virus, k, s1[i-1]) != vlen:
                        parent[(i, j, k)] = ((i-1, j-1, k), s1[i-1])
                    elif best == prev_len_top:
                        parent[(i, j, k)] = ((i-1, j, k), None)
                    else:
                        parent[(i, j, k)] = ((i, j-1, k), None)

    # Find best state
    best_state = max(dp.keys(), key=lambda x: dp[x])
    best_len = dp[best_state]

    if best_len == 0:
        return '0'

    # Reconstruct solution
    i, j, k = best_state
    res = []
    while parent.get((i, j, k)) is not None:
        prev_state, char = parent[(i, j, k)]
        if char:
            res.append(char)
        i, j, k = prev_state

    return ''.join(reversed(res))
