            if chars[start] != 'O':
                continue

            # Try removing consecutive O's starting from position start
            for end in range(start, n):
                if chars[end] != 'O':
                    break

                # Create new state after removing chocolates from start to end
                new_state = []
                for i in range(n):
                    if start <= i <= end:
                        new_state.append('.')
                    else:
                        new_state.append(chars[i])

                reachable.add(''.join(new_state))

        # Win if any move leads to opponent losing state
        for nextState in reachable:
            if not can_win(nextState):
                memo[state] = True
                return True

        memo[state] = False
        return False

    if can_win(state_string):
        return "Karlsson"
    else:
        return "Lillebror"
