Looking at this problem, I need to find either:
1. An independent set of size ⌈√n⌉, OR
2. A cycle of length at least ⌈√n⌉

This is a classic graph theory problem that can be solved using BFS to build a spanning tree. The deep nodes form natural independent sets (BFS layers), and back-edges in the BFS tree help us find cycles.

```python
import math
from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "1\n"

    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for line in lines[1:]:
        if line.strip():
            u, v = map(int, line.split())
            adj[u].append(v)
            adj[v].append(u)

    target = math.ceil(math.sqrt(n))

    # BFS from node 1 to build spanning tree and find depths
    visited = [False] * (n + 1)
    parent = [0] * (n + 1)
    depth = [-1] * (n + 1)

    queue = deque([1])
    visited[1] = True
    depth[1] = 0

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                depth[v] = depth[u] + 1
                queue.append(v)
            elif v != parent[u]:
                # Found a back edge (cycle in graph)
                pass

    # Group nodes by their BFS depth (these form natural independent sets)
    layers = [[] for _ in range(n)]
    for i in range(1, n + 1):
        if depth[i] >= 0:
            layers[depth[i]].append(i)

    # Check if any layer has enough vertices for independent set
    for d in range(n):
        if len(layers[d]) >= target:
            result = sorted(layers[d])[:target]
            return f"1\n" + " ".join(map(str, result))

    # No sufficient layer, must find a cycle
    # Check all edges to find one that creates a >= target length cycle
    for u in range(1, n + 1):
        for v in adj[u]:
            if depth[u] >= 0 and depth[v] >= 0:
                cycle_length = abs(depth[u] - depth[v]) + 1
                if cycle_length >= target:
                    # Build the cycle path from u to v via parent pointers
                    path = []
                    if depth[u] > depth[v]:
                        # v is ancestor of u
                        path.append(u)
                        curr = parent[u]
                        while curr != v:
                            path.append(curr)
                            curr = parent[curr]
                        path.append(v)
                    else:
                        # u is ancestor of v
                        path.append(v)
                        curr = parent[v]
                        while curr != u:
                            path.append(curr)
                            curr = parent[curr]
                        path.append(u)

                    return f"2\n{len(path)}\n" + " ".join(map(str, path))

    # Fallback - should never be reached given graph constraints
    return "1\n" + " ".join(map(str, range(1, target + 1)))
