def solution(input_str):
    parts = list(map(int, input_str.strip().split()))
    n, f1, f2, f3, c = parts

    MOD = 10**9 + 7

    if n == 1:
        return str(f1 % MOD)
    if n == 2:
        return str(f2 % MOD)
    if n == 3:
        return str(f3 % MOD)

    def mat_mul(A, B):
        n = len(A)
        C = [[0] * n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if A[i][k]:
                    for j in range(n):
                        C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
        return C

    def mat_pow(A, p):
        n = len(A)
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            result[i][i] = 1
        base = A
        while p > 0:
            if p % 2 == 1:
                result = mat_mul(result, base)
            base = mat_mul(base, base)
            p //= 2
        return result

    def tribonacci(k):
        """Computes the k-th term of tribonacci: 0,0,0,1,1,2,4,7,13,..."""
        if k <= 0:
            return 0
        if k == 1:
            return 0
        if k == 2:
            return 0
        if k == 3:
            return 1

        T = [[1, 1, 1], [1, 0, 0], [0, 1, 0]]
        T_res = mat_pow(T, k - 2)
        return T_res[0][2]

    # Exponents for f1, f2, f3 follow tribonacci with shifts
    f1_exp = tribonacci(n - 4)
    f2_exp = tribonacci(n - 3)
    f3_exp = tribonacci(n - 2)

    # For D_n: [D_k, D_{k-1}, D_{k-2}, k, 1] transition
    # Matrix size 5x5 to also track n and constant 1
    M = [[1, 1, 1, 2, MOD - 6],   # D
         [1, 0, 0, 0, 0],          # D_{k-1}
         [0, 1, 0, 0, 0],          # D_{k-2}
         [0, 0, 0, 1, 0],          # k -> k+1
         [0, 0, 0, 0, 1]]          # 1 -> 1

    # Initial state at k=n-3: [D_{n-3}, D_{n-4}, D_{n-5}, n-3, 1]
    # We compute M^(n-3) to advance from known values to position n
    M_res = mat_pow(M, n - 3)

    # Known values: D_1=0, D_2=0, D_3=0, D_4=2
    # State at position 4: [2, 0, 0, 4, 1]
    initial = [2, 0, 0, 4, 1]

    D_n = 0
    for j in range(5):
        D_n = (D_n + M_res[j][0] * initial[j]) % MOD

    # Compute final result
    res = pow(f1, f1_exp, MOD)
    res = (res * pow(f2, f2_exp, MOD)) % MOD
    res = (res * pow(f3, f3_exp, MOD)) % MOD
    res = (res * pow(c, D_n, MOD)) % MOD

    return str(res)
