    n, k = int(lines[0].strip()), int(lines[0].strip().split()[1])
    s = lines[1].strip()

    SIGNATURE = {('W'): 1, ('L'): -1, ('D'): 0}
    OFFSET = n

    # dp[i][diff_idx] = True if we can reach position i with diff = diff_idx - OFFSET
    dp = [[False] * (2 * INF) for _ in range(n + 1)]
    parent = [[None] * (2 * INF) for _ in range(n + 1)]

    INF = n + 1
    dp[0][0 + OFFSET] = True

    for i in range(n):
        current_diff = 0  # baseline diff at this point

        for diff_idx in range(2 * INF):
            if not dp[i][diff_idx]:
                continue

            current_diff = diff_idx - OFFSET

            # If we've already hit end condition before end of sequence, this path is invalid
            if abs(current_diff) == k and i < n - 1:
                continue

            # Determine possible characters
            if s[i] == 'W':
                chars = [1]
            elif s[i] == 'L':
                chars = [-1]
            elif s[i] == 'D':
                chars = [0]
            else:
                chars = [-1, 0, 1]

            for change in chars:
                new_diff = current_diff + change
                new_diff_idx = new_diff + OFFSET

                # Check if this would end the game prematurely
                if abs(new_diff) == k and i + 1 < n:
                    continue

                # Update dp
                dp[i + 1][new_diff_idx] = True
                parent[i + 1][new_diff_idx] = (s[i] if s[i] != '?' else ('W' if change == 1 else ('L' if change == -1 else 'D')), i, diff_idx)

    # Find final state with abs(diff) == k
    final_idx = None
    for diff_idx in range(n - k + OFFSET, n + k + OFFSET + 1):
        if 0 <= diff_idx < 2 * INF and dp[n][diff_idx] and abs(diff_idx - OFFSET) == k:
            final_idx = diff_idx
            break

    if final_idx is None:
        return "NO\n"

    # Reconstruct
    res = []
    pos = n
    idx = final_idx
    while pos > 0:
        char_info, prev_pos, prev_idx = parent[pos][idx]
        res.append(char_info)
        pos = prev_pos
        idx = prev_idx

    res.reverse()
    return ''.join(res) + '\n'

