4. Returns the first valid (x, y) with minimum product

```python
def solution(input_str):
    # Parse input
    parts = input_str.strip().split()
    if len(parts) < 3:
        return '-1'

    maxx, maxy, w = map(int, parts)

    # Early check: not enough total tickets possible
    if maxx * maxy < w:
        return '-1'

    # Precompute reversal of all numbers up to maxx and maxy
    def get_rev(n):
        return int(str(n)[::-1])

    # Optimization: cache reversals in dict
    rev_cache = {i: get_rev(i) for i in range(1, maxx + maxy + 2)}

    # Precompute which numbers are palindromes (x == rev(x))
    is_palindrome = lambda n: rev_cache[n] == n

    # For each possible x, track which y values are lucky
    # Since we want to minimize x*y, try small x first

    for x in range(1, maxx + 1):
        rev_x = rev_cache[x]

        # Count how many y values 1..maxy make (x, y) a lucky ticket
        # (x, y) is lucky iff x*y == rev_x * rev_y
        # For palindromes, rev_x = x, so we need y == rev_y
        # For non-palindromes, specific relationships required

        # Find minimum y for this x that gives >= w lucky pairs
        lucky_count_needed = w

        for y in range(1, maxy + 1):
            if (x * y == rev_x * rev_cache.get(y, 0)):
                # This (x, y) pair is a lucky ticket itself
                # Count how many pairs in [1,x] x [1,y] are lucky
                cnt = 0
                for i in range(1, x + 1):
                    for j in range(1, y + 1):
                        if i * j == rev_cache.get(i, 0) * rev_cache.get(j, 0):
                            cnt += 1

                if cnt >= w:
                    # Found a solution
                    return f"{x} {y}"

    return '-1'
