def solution(input_str):
    n, k, m = map(int, input_str.strip().split())

    MOD = 10**9 + 7

    # Edge case: k=1, we can start at any of n planets
    if k == 1:
        return str(n % MOD)

    if n == 1:
        return str(1 if k <= 1 else 0)

    # Memoization for DP
    memo = {}

    def count_sequences(current_pos, visited_mask, steps_left):
        """
        Count sequences starting from current_pos, 
        with visited_mask indicating which planets are visited,
        and steps_left remaining visits including current one.
        """
        if steps_left == 0:
            return 1

        # Create cache key
        state = (current_pos, visited_mask)
        if state in memo:
            return memo[state]

        count = 0

        # Try all valid next positions
        # From planet current_pos, can visit y where 1 <= y <= current_pos + m
        for y in range(1, min(n, current_pos + m + 1)):
            if not (visited_mask & (1 << (y - 1))):  # Planet y not visited
                new_mask = visited_mask | (1 << (y - 1))
                count = (count + count_sequences(y, new_mask, steps_left - 1)) % MOD

        memo[state] = count
        return count

    # Try all starting positions
    result = 0
    for start in range(1, n + 1):
        result = (result + count_sequences(start, 1 << (start - 1), k)) % MOD

    return str(result)


