            break
        N, K = map(int, lines[i].split())

        if K == 0:
            # Any permutation works, lexicographically smallest is 1 2 3 ... N
            results.append(' '.join(str(j) for j in range(1, N+1)))
        elif 2 * K > N:
            # Impossible to satisfy |P[i] - i| >= K for all positions
            results.append('-1')
        else:
            # Use the formula P[i] = (i + K - 1) % N + 1 (for 1-indexed positions)
            # This gives the lexicographically smallest valid permutation
            P = [(i + K - 1) % N + 1 for i in range(1, N+1)]
            results.append(' '.join(str(p) for p in P))

    return '\n'.join(results)
