def solution(input_str):
    """
    Solves the Silver ring problem where we need to determine which edges
    should be inside ('i') or outside ('o') the ring without intersections.
    """
    lines = input_str.strip().split('\n')
    if not lines:
        return 'Impossible'

    n, m = map(int, lines[0].split())
    edges = []
    for i in range(m):
        u, v = map(int, lines[1 + i].split())
        edges.append((i, u, v))

    def cross(a, b, c, d):
        """
        Check if two edges (a,b) and (c,d) cross on the ring.
        After normalizing each edge so min < max:
        - They cross if they don't share endpoints AND exactly one
          endpoint of one edge lies strictly between the endpoints of the other.
        """
        a, b = min(a, b), max(a, b)
        c, d = min(c, d), max(c, d)

        # Check if they share any endpoint - no crossing if they do
        if a == c or a == d or b == c or b == d:
            return False

        # Check crossing: exactly one endpoint of (c,d) is in linear interval (a,b)
        c_in = (a < c < b)
        d_in = (a < d < b)

        return c_in != d_in

    # Build conflict graph where edges that cross cannot be same side (different colors)
    adj = [[] for _ in range(m)]

    for i in range(m):
        for j in range(i + 1, m):
            if cross(edges[i][1], edges[i][2], edges[j][1], edges[j][2]):
                adj[i].append(j)
                adj[j].append(i)

    # 2-color the graph (bipartite check)
    visited = [False] * m
    color = [0] * m  # 1 for 'i', -1 for 'o'
    possible = True

    def dfs(u, c):
        nonlocal possible
        visited[u] = True
        color[u] = c

        for v in adj[u]:
            if not visited[v]:
                if not dfs(v, -c):
                    possible = False
                    return
            else:
                if color[v] == c:
                    possible = False
                    return
        return True

    for i in range(m):
        if not visited[i]:
            if not dfs(i, 1):
                break

    if possible:
        result = []
        for i in range(m):
            result.append('i' if color[i] == 1 else 'o')
        return ''.join(result)
    else:
        return 'Impossible'


